#!/usr/bin/env python3
"""
Adds the Inventory Management feature to gentie-router.

    cd <repo root>            # the folder containing config.py
    python apply_inventory.py

Safe to re-run (already-applied edits are skipped). Handles Windows (CRLF) line endings.
"""
import base64, pathlib, sys

ROOT = pathlib.Path.cwd()
if not (ROOT / "config.py").exists() or not (ROOT / "backend" / "app.py").exists():
    sys.exit("Run this from the repo root (the folder that contains config.py and backend/).")

NEW_FILES = {'backend/inventory.py': '', 'backend/test_inventory.py': '', 'data/inventory/catalog.json': ''}
EDITS = [('backend/app.py', 'GET  /bounds           study-region bbox + data provenance', 'POST /inventory        {start, end, voltage_kv?, capacity_mw?, need_by_weeks?, market?, include_terminals?}\n                       -> BOM, supplier fill, long-lead order plan, on-time probability (see backend/inventory.py)\nGET  /inventory/catalog  the simulated supplier catalog (suppliers, stock, lead-time bands, market scenarios)\nGET  /bounds           study-region bbox + data provenance'), ('backend/app.py', 'from typing import Annotated\n', 'from typing import Annotated, Literal\n'), ('backend/app.py', 'from backend import worker\n', 'from backend import inventory, worker\n'), ('backend/app.py', '@app.post("/route")\nasync def route(req: RouteRequest):\n    key = tuple(round(v, CACHE_KEY_DECIMALS) for v in (*req.start, *req.end))\n    status, body, cache_state = await state["cache"].get_or_compute(key, lambda: _compute(req.start, req.end))\n    return Response(content=body, status_code=status, media_type="application/json", headers={"X-Cache": cache_state})\n', 'async def _route_cached(start, end):\n    key = tuple(round(v, CACHE_KEY_DECIMALS) for v in (*start, *end))\n    return await state["cache"].get_or_compute(key, lambda: _compute(start, end))\n\n\n@app.post("/route")\nasync def route(req: RouteRequest):\n    status, body, cache_state = await _route_cached(req.start, req.end)\n    return Response(content=body, status_code=status, media_type="application/json", headers={"X-Cache": cache_state})\n\n\nclass InventoryRequest(BaseModel):\n    start: LonLat\n    end: LonLat\n    voltage_kv: Literal[69, 138] = 69\n    capacity_mw: float = Field(100, gt=0, le=1000, description="project size; sets the generator step-up transformer MVA")\n    need_by_weeks: float = Field(104, ge=0, le=520, description="weeks from today until construction must start")\n    market: Literal["current", "tight", "crisis"] = "current"\n    include_terminals: bool = Field(True, description="include breakers, switches, relays and the GSU at the two ends")\n\n\n@app.post("/inventory")\nasync def inventory_assess(req: InventoryRequest):\n    """Re-uses /route (and its cache), so asking for inventory right after a route costs almost nothing extra."""\n    status, body, _ = await _route_cached(req.start, req.end)\n    if status != 200:\n        return Response(content=body, status_code=status, media_type="application/json")\n    params = req.model_dump(exclude={"start", "end"})\n    return await run_in_threadpool(inventory.assess, json.loads(body), **params)\n\n\n@app.get("/inventory/catalog")\ndef inventory_catalog():\n    return inventory.load_catalog()\n'), ('frontend/index.html', '      <ul id="triggers" class="triggers"></ul>\n', '      <ul id="triggers" class="triggers"></ul>\n\n      <h3>Materials &amp; long-lead procurement</h3>\n      <div class="invctl">\n        <label>Project MW <input id="invMw" type="number" min="5" max="1000" value="100"></label>\n        <label>Line kV <select id="invKv"><option value="69">69</option><option value="138">138</option></select></label>\n        <label>Construction starts in (wks) <input id="invNeed" type="number" min="0" max="520" value="104"></label>\n        <label>Supply market <select id="invMarket"><option value="current">Current</option><option value="tight">Tight</option><option value="crisis">Crisis</option></select></label>\n      </div>\n      <div id="invSummary" class="note"></div>\n      <ul id="invList" class="inv"></ul>\n      <div id="invNote" class="note muted small"></div>\n'), ('frontend/app.js', '      ol.appendChild(li);\n    }\n  }\n\n  // Plain-language explanation of the demo route', '      ol.appendChild(li);\n    }\n    invProps = p;\n    refreshInventory();\n  }\n\n  // Plain-language explanation of the demo route'), ('frontend/app.js', '  // ------------------------------------------------------------------ boot\n', '  // ------------------------------------------------------------------ materials & long-lead procurement\n  let invProps = null, invSeq = 0;\n  const esc = (t) => String(t).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", \'"\': "&quot;" }[c]));\n\n  async function refreshInventory() {\n    if (!invProps) return;\n    const seq = ++invSeq, sum = $("invSummary"), list = $("invList");\n    if (!state.backendOk) {\n      sum.textContent = "The supplier simulation needs the backend (not available in demo mode).";\n      list.innerHTML = "";\n      return;\n    }\n    sum.textContent = "Checking supplier availability…";\n    try {\n      const r = await getJson("/inventory", {\n        method: "POST", headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({\n          start: invProps.start, end: invProps.end,\n          capacity_mw: +$("invMw").value || 100, voltage_kv: +$("invKv").value,\n          need_by_weeks: +$("invNeed").value || 0, market: $("invMarket").value,\n        }),\n      });\n      if (seq === invSeq) renderInventory(r);          // ignore answers superseded by a newer request\n    } catch (err) {\n      if (seq === invSeq) { sum.textContent = `Inventory check failed: ${err.message}`; list.innerHTML = ""; }\n    }\n  }\n\n  function renderInventory(r) {\n    const s = r.summary, e = s.earliest_construction_start_weeks;\n    const cls = { VIABLE: "good", "AT RISK": "mid", "NOT VIABLE": "bad" }[s.verdict];\n    const parts = [`<b class="${cls}">${s.verdict}</b>: ${Math.round(100 * s.p_materials_on_time)}% chance every item arrives in time for construction to start in ${r.params.need_by_weeks} wks.`];\n    if (e.p50 != null) parts.push(`Earliest start the materials allow: week ${Math.round(e.p50)} typical, week ${Math.round(e.p90)} cautious.`);\n    if (s.unqualified.length) parts.push(`<span class="bad">No qualified supplier:</span> ${s.unqualified.map(esc).join(", ")}.`);\n    if (s.critical_path_drivers.length) {\n      parts.push(`Holding up the schedule: ${s.critical_path_drivers.map((d) => `${esc(d.name)} (${Math.round(100 * d.share)}%)`).join(", ")}.`);\n    }\n    parts.push(`Materials ≈ ${fmtUsd(s.est_material_cost_usd)} (placeholder prices).`);\n    $("invSummary").innerHTML = parts.join("<br>");\n    const byId = Object.fromEntries(r.lines.map((l) => [l.id, l]));\n    $("invList").innerHTML = r.order_plan.map((o) => {\n      const l = byId[o.id];\n      const eta = l.eta_weeks.p50 == null ? "no ETA" : `ETA ${Math.round(l.eta_weeks.p50)}–${Math.round(l.eta_weeks.p90)} wks`;\n      const stock = l.in_stock_qty > 0 ? ` · ${l.in_stock_qty} ${l.unit} in stock` : "";\n      return `<li><div class="r1"><span class="nm">${o.long_lead ? \'<span class="ll">LONG-LEAD</span>\' : ""}${esc(l.name)}</span>\n        <span class="st ${l.status.toLowerCase().replaceAll(" ", "-")}">${l.status}</span></div>\n        <div class="r2 muted">${l.qty} ${l.unit} · ${eta}${stock}</div><div class="r2">${esc(o.action)}</div></li>`;\n    }).join("");\n    $("invNote").textContent = `Simulated suppliers and placeholder lead times (${r.params.trials} Monte Carlo trials; market: ${r.params.market_label}). Edit data/inventory/catalog.json.`;\n  }\n  ["invMw", "invKv", "invNeed", "invMarket"].forEach((id) => $(id).addEventListener("change", refreshInventory));\n\n  // ------------------------------------------------------------------ boot\n')]
APPENDS = [('config.py', '\n# --------------------------------------------------------------------------\n# Inventory / procurement simulation (backend/inventory.py)\n# --------------------------------------------------------------------------\nINVENTORY_CATALOG = DATA_DIR / "inventory" / "catalog.json"\nLONG_LEAD_WEEKS = 40         # catalog items whose typical (p50) lead time is at least this are "long-lead"\nINVENTORY_TRIALS = 600       # Monte Carlo trials per assessment\n', 'INVENTORY_CATALOG'), ('frontend/style.css', '\n/* materials & long-lead procurement */\n.invctl { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 8px; margin-bottom: 8px; }\n.invctl label { display: flex; flex-direction: column; gap: 2px; font-size: 11px; color: var(--muted); }\n.invctl input, .invctl select { background: rgba(255, 255, 255, 0.06); color: var(--fg); border: 1px solid var(--line);\n  border-radius: 5px; padding: 3px 5px; font: inherit; }\n.note .mid { color: #ffc65c; }\n.inv { margin: 8px 0 0; padding: 0; list-style: none; font-size: 12px; }\n.inv li { padding: 5px 0; border-bottom: 1px solid var(--line); }\n.inv .r1 { display: flex; justify-content: space-between; gap: 8px; align-items: baseline; }\n.inv .r2 { font-size: 11px; }\n.inv .nm { font-weight: 500; }\n.inv .ll { display: inline-block; margin-right: 6px; padding: 0 5px; border-radius: 3px; font-size: 9px; letter-spacing: 0.4px;\n  background: rgba(181, 124, 255, 0.2); color: #d6b8ff; border: 1px solid rgba(181, 124, 255, 0.5); vertical-align: 1px; }\n.inv .st { flex: none; font-size: 9px; padding: 1px 6px; border-radius: 999px; border: 1px solid var(--line); }\n.inv .st.in-stock, .inv .st.on-track { color: #7ef0ae; border-color: rgba(61, 220, 132, 0.4); }\n.inv .st.at-risk { color: #ffc65c; border-color: rgba(255, 176, 32, 0.5); }\n.inv .st.late, .inv .st.no-qualified-supplier { color: #ff9a9a; border-color: rgba(255, 120, 120, 0.5); }\n', 'materials & long-lead procurement')]


def read(path):
    raw = path.read_bytes().decode("utf-8")
    crlf = "\r\n" in raw
    return raw.replace("\r\n", "\n"), crlf


def write(path, text, crlf):
    path.write_bytes((text.replace("\n", "\r\n") if crlf else text).encode("utf-8"))


for rel, blob in NEW_FILES.items():
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(blob))
    print(f"  wrote   {rel}")

for rel, old, new in EDITS:
    p = ROOT / rel
    text, crlf = read(p)
    if new in text:
        print(f"  skipped {rel} (already applied)")
        continue
    if text.count(old) != 1:
        sys.exit(f"ERROR: expected exactly one match in {rel} for:\n{old[:120]!r}\n"
                 "The file differs from the version this script was written for (commit 40c2e2f).")
    write(p, text.replace(old, new), crlf)
    print(f"  edited  {rel}")

for rel, block, marker in APPENDS:
    p = ROOT / rel
    text, crlf = read(p)
    if marker in text:
        print(f"  skipped {rel} (already applied)")
        continue
    write(p, text.rstrip("\n") + "\n" + block, crlf)
    print(f"  edited  {rel}")

print("\nDone. Next: python -m backend.test_inventory")